extends Node2D

# Archivio dei personaggi con affinita' e mappa delle espressioni emotive
var characters: Dictionary = {
	"hero": {
		"name": "Eldrin",
		"affinity": 10,
		"emotions": {
			"neutral": "Serio e composto",
			"happy": "Sorpreso e felice",
			"angry": "Accigliato e teso"
		}
	},
	"mage": {
		"name": "Lyra",
		"affinity": 25,
		"emotions": {
			"neutral": "Calma e riflessiva",
			"happy": "Sorriso raggiante"
		}
	}
}

var current_character: String = "hero"
var current_emotion: String = "neutral"


func _ready() -> void:
	update_display()


func set_speaker(char_id: String) -> bool:
	# Cambia personaggio attivo se registrato nel dizionario
	if char_id in characters:
		current_character = char_id
		current_emotion = "neutral"
		update_display()
		return true
	return false


func get_speaker_name(char_id: String) -> String:
	# Restituisce il nome leggibile o 'Sconosciuto' se assente
	if char_id in characters:
		return characters[char_id]["name"]
	return "Sconosciuto"


func update_display() -> void:
	# Aggiorna il testo a video leggendo i dati dal dizionario
	if current_character in characters:
		var profile: Dictionary = characters[current_character]
		var speaker_name: String = profile["name"]
		var affinity: int = profile["affinity"]
		var emotion_map: Dictionary = profile["emotions"]
		var emotion_text: String = emotion_map.get(current_emotion, "Indifferente")
		$Label.text = "%s (Affinita': %d)\nEspressione: %s" % [speaker_name, affinity, emotion_text]

