		"emotions": {
			"neutral": "Calma e riflessiva",
			"happy": "Sorriso raggiante"
		}
	}
}

var current_character: String = "hero"
var current_emotion: String = "neutral"


func _ready() -> void:
	update_display()


func set_speaker(char_id: String) -> bool:
	# Cambia personaggio attivo se registrato nel dizionario
	if char_id in characters:
		current_character = char_id
		current_emotion = "neutral"
		update_display()
		return true
	return false


func get_speaker_name(char_id: String) -> String:
	# Restituisce il nome leggibile o 'Sconosciuto' se assente
	if char_id in characters:
		return characters[char_id]["name"]
	return "Sconosciuto"


func add_emotion(char_id: String, emotion_id: String, description: String) -> bool:
	# Verifica esistenza personaggio nel dizionario principale
	if not (char_id in characters):
		return false

	var emotions: Dictionary = characters[char_id]["emotions"]

	# Non sovrascrive emozioni gia' definite
	if emotion_id in emotions:
		return false

	emotions[emotion_id] = description
	if char_id == current_character:
		update_display()
	return true


func change_affinity(char_id: String, amount: int) -> int:
	# Restituisce -1 se il personaggio non esiste nel dizionario
	if not (char_id in characters):
		return -1

	var new_affinity: int = characters[char_id]["affinity"] + amount
	if new_affinity < 0:
		new_affinity = 0

	characters[char_id]["affinity"] = new_affinity
	update_display()
	return new_affinity


func update_display() -> void:
	# Aggiorna il testo a video leggendo i dati dal dizionario
